using System;
using System.Linq;
using System.Drawing;
using System.Collections.Generic;
using System.Windows.Forms;

namespace GearLab {
 public sealed class SettingsForm:Form {
  int section;bool selecting;readonly Dictionary<SafeNumber,Action<decimal>> numericEdits=new Dictionary<SafeNumber,Action<decimal>>();
  ComboBox languageChoice;bool syncingLanguage;double observedSpeed;AppSettings draft;readonly Panel content=new Panel();readonly Label message=new Label();readonly ListBox sections=new ListBox();readonly Dictionary<string,TextBox> colorFields=new Dictionary<string,TextBox>();
  internal AppSettings Draft{get{return draft;}}
  public SettingsForm(Control owner){draft=AppSettings.Current.Clone();observedSpeed=AppSettings.Current.AnimationScale;Text="Настройки GearLab";Size=new Size(920,720);MinimumSize=new Size(720,540);StartPosition=FormStartPosition.CenterParent;Font=new Font("Segoe UI",9);var footer=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=52,Padding=new Padding(10),WrapContents=false};var save=new Button{Text="Применить",Width=125,Height=30};save.Click+=(s,e)=>ApplyDraft();var reset=new Button{Text="Стандартные",Width=145,Height=30};reset.Click+=(s,e)=>{draft=new AppSettings();ShowSection();message.Text="Стандартные значения подготовлены. Нажмите «Применить».";};var cancel=new Button{Text="Отмена",Width=110,Height=30};cancel.Click+=(s,e)=>{draft=AppSettings.Current.Clone();if(Modal){DialogResult=DialogResult.Cancel;Close();}else{ShowSection();message.Text="Несохранённые изменения отменены.";}};footer.Controls.AddRange(new Control[]{save,reset,cancel});message.AutoSize=false;message.Width=430;message.Height=35;footer.Controls.Add(message);Controls.Add(footer);CancelButton=cancel;AppSettings.Changed+=SynchronizeLanguage;Disposed+=(s,e)=>AppSettings.Changed-=SynchronizeLanguage;
   sections.Dock=DockStyle.Left;sections.Width=175;sections.BorderStyle=BorderStyle.None;sections.ItemHeight=34;sections.DrawMode=DrawMode.OwnerDrawFixed;sections.Items.AddRange(new[]{"Оформление","Цвета","3D и анимация","Язык","Сохранение"});sections.DrawItem+=(s,e)=>{if(e.Index<0)return;using(var b=new SolidBrush(UiPalette.Get((e.State&DrawItemState.Selected)!=0?"Selection":"Header")))e.Graphics.FillRectangle(b,e.Bounds);TextRenderer.DrawText(e.Graphics,I18n.T(sections.Items[e.Index].ToString()),Font,new Rectangle(e.Bounds.X+14,e.Bounds.Y,e.Bounds.Width-18,e.Bounds.Height),UiPalette.Get("Text"),TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);};content.Dock=DockStyle.Fill;content.AutoScroll=true;Controls.Add(content);Controls.Add(sections);content.BringToFront();sections.SelectedIndexChanged+=(s,e)=>{if(selecting)return;try{CaptureEditors();section=sections.SelectedIndex;ShowSection();}catch(Exception ex){message.Text=ex.Message;selecting=true;sections.SelectedIndex=section;selecting=false;}};sections.SelectedIndex=0;AppSettings.Apply(this);if(!string.IsNullOrEmpty(AppSettings.LoadWarning))message.Text=AppSettings.LoadWarning;
  }
  void SynchronizeLanguage(){if(IsDisposed)return;double speed=AppSettings.Current.AnimationScale;if(Math.Abs(speed-observedSpeed)>1e-9&&Math.Abs(draft.AnimationScale-observedSpeed)<1e-9){draft.AnimationScale=speed;foreach(var n in numericEdits.Keys)if(n.AccessibleName=="Скорость анимации ×")n.Commit((decimal)speed);}observedSpeed=speed;draft.Language=AppSettings.Current.Language;if(languageChoice!=null&&!languageChoice.IsDisposed){syncingLanguage=true;try{languageChoice.SelectedIndex=(int)draft.Language;}finally{syncingLanguage=false;}}}
  internal bool ApplyDraft(){try{CaptureEditors();AppSettings.Commit(draft);draft=AppSettings.Current.Clone();ShowSection();message.Text=I18n.T("Настройки сохранены.");return true;}catch(Exception ex){message.Text=I18n.T(ex.Message);return false;}}
  void CaptureEditors(){foreach(var edit in numericEdits){decimal value;if(!edit.Key.TryRead(out value))throw new Exception(I18n.T("Проверьте поле: ")+I18n.T(edit.Key.AccessibleName));edit.Value(value);}foreach(var pair in colorFields){if(!System.Text.RegularExpressions.Regex.IsMatch(pair.Value.Text.Trim(),"^#[0-9a-fA-F]{6}$"))throw new Exception(I18n.T("Недопустимый цвет: ")+pair.Key);draft.Colors[pair.Key]=pair.Value.Text.Trim();}}
  FlowLayoutPanel Stack(){var p=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(22,18,22,25)};content.Controls.Add(p);return p;}
  void Title(FlowLayoutPanel p,string text){p.Controls.Add(new Label{Text=text,AutoSize=true,Font=new Font(Font.FontFamily,13,FontStyle.Bold),Margin=new Padding(0,0,0,16)});}
  void Note(FlowLayoutPanel p,string text){p.Controls.Add(new Label{Text=text,MaximumSize=new Size(510,0),AutoSize=true,Margin=new Padding(0,8,0,15)});}
  ComboBox Choice(FlowLayoutPanel p,string label,string[] items,int selected,Action<int> set){Note(p,label);var c=new EditorComboBox{Width=330,DropDownStyle=ComboBoxStyle.DropDownList};c.Items.AddRange(items);c.SelectedIndex=selected;c.SelectedIndexChanged+=(s,e)=>set(c.SelectedIndex);p.Controls.Add(c);return c;}
  void Number(FlowLayoutPanel p,string label,decimal min,decimal max,int digits,decimal value,Action<decimal> set){Note(p,label);var n=new SafeNumber{Minimum=min,Maximum=max,DecimalPlaces=digits,Increment=digits==0?1:.1m,Width=190,AccessibleName=label};n.Commit(value);numericEdits[n]=set;n.ValueChanged+=(s,e)=>set(n.Value);p.Controls.Add(n);}
  void Toggle(FlowLayoutPanel p,string text,bool value,Action<bool> set){var c=new CheckBox{Text=text,Checked=value,AutoSize=true,MaximumSize=new Size(510,0),Margin=new Padding(0,10,0,8)};c.CheckedChanged+=(s,e)=>set(c.Checked);p.Controls.Add(c);}
  void ShowSection(){content.SuspendLayout();foreach(Control c in content.Controls.Cast<Control>().ToArray())c.Dispose();content.Controls.Clear();colorFields.Clear();numericEdits.Clear();var p=Stack();switch(sections.SelectedIndex){
   case 0:Title(p,"Оформление рабочего пространства");Note(p,"Компактные панели, тёмные редакторы и оранжевый акцент в стиле Blender.");Choice(p,"Готовая тема (заменяет выбранные цвета)",new[]{"Blender — тёмная","Blender — светлая"},draft.Theme==GearTheme.Тёмная?0:1,i=>{draft.Theme=i==0?GearTheme.Тёмная:GearTheme.Светлая;draft.Colors.Clear();message.Text="Тема подготовлена. Нажмите «Применить».";});Note(p,"Каждый цвет можно изменить в разделе «Цвета». Изменения действуют во всех открытых и новых рабочих пространствах.");break;
   case 1:Title(p,"Цвета интерфейса и сцены");Note(p,"Выберите образец или введите цвет #RRGGBB. Цвета деталей и файлов экспорта сохраняются.");string[] names={"Фон окна","Панели","Заголовки и меню","Поля ввода","Основной текст","Вторичный текст","Границы","Акцент","Выделение","Фон 3D / чертежа","Сетка","Ось X","Ось Y","Ось Z","Успех","Предупреждение","Ошибка"};for(int i=0;i<UiPalette.Keys.Length;i++){string key=UiPalette.Keys[i];var row=new FlowLayoutPanel{Width=505,Height=34,WrapContents=false,Margin=new Padding(0,2,0,2)};row.Controls.Add(new Label{Text=names[i],Width=240,Height=28,TextAlign=ContentAlignment.MiddleLeft});var swatch=new PaletteButton{Width=48,Height=26,Swatch=UiPalette.Get(draft,key)};var hex=new TextBox{Width=112,Text=ColorTranslator.ToHtml(swatch.Swatch)};colorFields[key]=hex;hex.TextChanged+=(s,e)=>{try{if(System.Text.RegularExpressions.Regex.IsMatch(hex.Text,"^#[0-9a-fA-F]{6}$")){draft.Colors[key]=hex.Text;swatch.Swatch=ColorTranslator.FromHtml(hex.Text);swatch.Invalidate();}}catch{}};swatch.Click+=(s,e)=>{using(var d=new ColorDialog{Color=swatch.Swatch,FullOpen=true})if(d.ShowLocalizedDialog(this)==DialogResult.OK)hex.Text="#"+d.Color.R.ToString("X2")+d.Color.G.ToString("X2")+d.Color.B.ToString("X2");};row.Controls.Add(swatch);row.Controls.Add(hex);p.Controls.Add(row);}break;
   case 2:Title(p,"3D и анимация");Choice(p,"Качество предпросмотра",new[]{"Быстрый","Обычный","Подробный"},(int)draft.Quality,i=>draft.Quality=(GearQuality)i);Note(p,"Качество меняет детализацию предпросмотра. Точная геометрия STEP и параметры механизма сохраняются.");Number(p,"Чувствительность вращения камеры",1,30,1,(decimal)draft.OrbitSensitivity,v=>draft.OrbitSensitivity=(double)v);Number(p,"Скорость анимации ×",.01m,10,2,(decimal)draft.AnimationScale,v=>draft.AnimationScale=(double)v);Toggle(p,"Привязка перемещения к сетке",draft.SnapEnabled,v=>draft.SnapEnabled=v);Number(p,"Шаг сетки / перемещения, мм",.01m,100,2,(decimal)draft.SnapStep,v=>draft.SnapStep=(double)v);break;
   case 3:Title(p,"Язык интерфейса");languageChoice=Choice(p,"Язык",new[]{"Русский","English"},(int)draft.Language,i=>{if(syncingLanguage)return;try{AppSettings.SetLanguage((GearLanguage)i);draft.Language=AppSettings.Current.Language;message.Text="Язык изменён и сохранён.";}catch(Exception ex){message.Text=ex.Message;}});Note(p,"Язык меняется сразу и сохраняется между запусками. Имена проектов и числовые параметры сохраняются.");break;
   case 4:Title(p,"Сохранение и восстановление");Toggle(p,"Автосохранение рабочих проектов",draft.AutoSave,v=>draft.AutoSave=v);Number(p,"Интервал автосохранения, с",15,600,0,draft.AutoSaveSeconds,v=>draft.AutoSaveSeconds=(int)v);Note(p,"Автосохранение создаёт восстановительные копии проектов робота. Для записи основного файла используйте «Сохранить».");Note(p,"Папка настроек и восстановительных копий:");var path=new TextBox{Text=AppSettings.Folder,Name="UserPath",ReadOnly=true,Width=505};p.Controls.Add(path);break;
  }AppSettings.Apply(content);sections.Invalidate();content.ResumeLayout(true);}
  sealed class PaletteButton:Button {public Color Swatch;protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);using(var b=new SolidBrush(Swatch))e.Graphics.FillRectangle(b,5,5,Width-10,Height-10);}}
 }
